import os

def transform(grid):
    """
    Rule: For each row, find runs of 0s between non-zero values (2 or 8) on BOTH sides.
    If run length >= 2, change all cells in run to 8.
    This acts horizontally per row.
    """
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0
    output = [row[:] for row in grid]

    for r in range(height):
        for c in range(width):
            if output[r][c] == 0:
                # Check if surrounded by non-zero on both sides
                left = output[r][c-1] if c > 0 else None
                right = output[r][c+1] if c < width-1 else None

                if left is None or right is None:
                    continue  # not surrounded
                if left == 0 or right == 0:
                    continue  # run, check length

                # Check run length
                start, end = c, c
                while start > 0 and output[r][start-1] == 0:
                    start -= 1
                while end < width-1 and output[r][end+1] == 0:
                    end += 1

                run_length = end - start + 1
                if left != 0 and right != 0 and run_length >= 2:
                    for k in range(start, end + 1):
                        output[r][k] = 8
                else:
                    # Single cell surrounded by non-zeros, stays 0
                    pass

    return output

